"""AcmeCSV invoice parser."""

import csv
import io


def _parse_amount(amount_str):
    """Convert a currency string to an integer number of cents."""
    s = amount_str.strip()
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1].strip()
    if s.startswith("$"):
        s = s[1:].strip()
    s = s.replace(",", "")
    if not s:
        value = 0
    elif "." in s:
        dollars, cents = s.split(".", 1)
        cents = (cents + "00")[:2]
        value = int(dollars or "0") * 100 + int(cents)
    else:
        value = int(s) * 100
    return -value if negative else value


def parse(text):
    """Parse AcmeCSV invoice text into a list of row dicts.

    Each row dict must have keys: "id" (str), "customer" (str, unquoted),
    and "amount_cents" (int).
    """
    if not text or not str(text).strip():
        return []
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        return []
    header = [h.strip() for h in header]
    rows = []
    for parts in reader:
        if not parts or all(not p.strip() for p in parts):
            continue
        record = dict(zip(header, parts))
        rows.append(
            {
                "id": str(record["id"]),
                "customer": record["customer"],
                "amount_cents": _parse_amount(record["amount"]),
            }
        )
    return rows
